kql.query:
let windowStart = datetime(2026-11-17T00:00:00Z);
let windowEnd = datetime(2026-11-18T00:00:00Z);
let prefixes = dynamic(["i1", "glm-", "probe"]);
KubeEvents
| where TimeGenerated between (windowStart .. windowEnd)
| where Reason has_any ("Created", "Started", "Scheduled", "SuccessfulCreate")
    or Message has_any ("secrets", "get secret", "list secrets")
| extend SuspectName = Name has_any (prefixes)
| project TimeGenerated, Namespace, Name, Kind, Reason, Message, SuspectName
| order by SuspectName desc, TimeGenerated asc
